-- FetUre: черновой набор правовых документов (ru) для проверки на новом сервере.
-- Тексты перенесены из прежней базы как есть: в них остались пометки «До публикации заполнить» —
-- перед запуском для пользователей их заменяет юрист (админка → документы: save + publish).
-- Регистрация закрыта, пока не опубликованы все четыре обязательных документа: terms, privacy, community, adult-content.
-- Безопасно запускать повторно: уже опубликованный документ пропускается.
--   docker compose exec -T db psql -U postgres -d feture -v ON_ERROR_STOP=1 < seed-documents.sql
do $seed$
declare r jsonb; d record;
begin
  if not exists (select 1 from public.feture_document_versions where document_key='terms' and locale='ru') then
    r:=public.feture_document_save('terms','ru',0,$t$Условия использования$t$,$j$[{"type": "heading", "text": "Назначение сервиса"}, {"type": "paragraph", "text": "FetUre помогает совершеннолетним исследовать собственные интересы, вести личные записи и общаться по взаимному согласию. Результаты опросников — материал для размышления, а не диагноз, терапия или медицинская рекомендация."}, {"type": "heading", "text": "Аккаунт и доступ"}, {"type": "paragraph", "text": "Используйте свой аккаунт. Для чувствительных функций нужны действующее подтверждение совершеннолетия и принятие актуальных обязательных документов. Проверка возраста сама по себе не разрешает доступ к чужим материалам или общению."}, {"type": "heading", "text": "Согласие и ответственность"}, {"type": "paragraph", "text": "Границы, публикации и разрешения можно менять. Доступ к профилю не означает согласие на контакт, встречу или практику. Любой участник может отказаться без объяснений. Не размещайте чужие данные и материалы без соответствующего разрешения."}, {"type": "heading", "text": "До публикации заполнить"}, {"type": "list", "items": ["Юрлицо, адрес и применимое право.", "Контакт поддержки и процедура обжалования.", "Территории обслуживания, ограничения и порядок прекращения аккаунта.", "Правила ответственности и изменения условий после юридической проверки."]}]$j$::jsonb,true);
    if (r->>'ok')<>'true' then raise exception 'save terms: %',r; end if;
    r:=public.feture_document_publish('terms','ru',1,true,clock_timestamp());
    if (r->>'ok')<>'true' then raise exception 'publish terms: %',r; end if;
  end if;
  if not exists (select 1 from public.feture_document_versions where document_key='privacy' and locale='ru') then
    r:=public.feture_document_save('privacy','ru',0,$t$Конфиденциальность$t$,$j$[{"type": "heading", "text": "Какие сведения обрабатываются"}, {"type": "paragraph", "text": "Сервис использует данные аккаунта, технические данные сессии и сведения, которые вы отдельно добавляете: профиль, интересы, ответы, записи и публикации. Не добавляйте сведения о третьих лицах без основания. Интересы и записи могут раскрывать чувствительную информацию."}, {"type": "heading", "text": "Управление видимостью"}, {"type": "paragraph", "text": "Личные материалы по умолчанию закрыты. Публикация, доступ конкретному человеку, сравнение и участие в знакомствах требуют отдельных действий. Разрешение относится только к выбранным сведениям; его отзыв прекращает новые обращения через сервис. Уже скачанный файл или сделанный снимок экрана отозвать невозможно."}, {"type": "heading", "text": "Проверка возраста"}, {"type": "paragraph", "text": "Сервису нужен минимальный результат проверки. Документы и биометрические сведения не должны попадать в профиль, аналитику или журнал событий. До подключения провайдера описать его роль, процедуру и отдельные сроки хранения."}, {"type": "heading", "text": "До публикации заполнить"}, {"type": "list", "items": ["Оператор данных, правовые основания и контакты для запросов.", "Точный перечень обработчиков, регионы и международная передача.", "Сроки хранения каждого класса данных, резервных копий и исключений.", "Порядок доступа, исправления, экспорта, удаления и обращения к регулятору."]}]$j$::jsonb,true);
    if (r->>'ok')<>'true' then raise exception 'save privacy: %',r; end if;
    r:=public.feture_document_publish('privacy','ru',1,true,clock_timestamp());
    if (r->>'ok')<>'true' then raise exception 'publish privacy: %',r; end if;
  end if;
  if not exists (select 1 from public.feture_document_versions where document_key='community' and locale='ru') then
    r:=public.feture_document_save('community','ru',0,$t$Правила сообщества$t$,$j$[{"type": "heading", "text": "Общение по взаимному согласию"}, {"type": "paragraph", "text": "Уважайте отказ, паузу и изменение границ. Не давите на участников и не выдавайте просмотр профиля, подписку или совпадение интересов за согласие на интимный контакт."}, {"type": "heading", "text": "Запрещённые действия"}, {"type": "list", "items": ["Участие несовершеннолетних и материалы сексуальной эксплуатации несовершеннолетних.", "Угрозы, преследование, шантаж, раскрытие чужих персональных данных.", "Интимные материалы без согласия изображённых людей, скрытая съёмка и выдача себя за другого человека.", "Призывы к насилию, незаконная деятельность, мошенничество и спам."]}, {"type": "heading", "text": "Жалобы и ограничения"}, {"type": "paragraph", "text": "При нарушении используйте жалобу и блокировку. Жалоба запускает рассмотрение и сама по себе не доказывает вину. Модерация может снять материал или ограничить функции; процедура уведомления и обжалования должна быть доступна участнику."}, {"type": "heading", "text": "До публикации заполнить"}, {"type": "paragraph", "text": "Контакт модерации, сроки рассмотрения, правила сохранения доказательств и порядок обжалования."}]$j$::jsonb,true);
    if (r->>'ok')<>'true' then raise exception 'save community: %',r; end if;
    r:=public.feture_document_publish('community','ru',1,true,clock_timestamp());
    if (r->>'ok')<>'true' then raise exception 'publish community: %',r; end if;
  end if;
  if not exists (select 1 from public.feture_document_versions where document_key='adult-content' and locale='ru') then
    r:=public.feture_document_save('adult-content','ru',0,$t$Совершеннолетие и согласие$t$,$j$[{"type": "heading", "text": "Доступ только совершеннолетним"}, {"type": "paragraph", "text": "Чувствительные функции предназначены только для лиц 18 лет и старше. Местные требования могут устанавливать дополнительные ограничения. Не обходите проверку и не предоставляйте аккаунт другому человеку."}, {"type": "heading", "text": "Разрешение на материалы"}, {"type": "paragraph", "text": "Публикуйте только материалы, которыми вы вправе распоряжаться. Для изображения другого человека нужны его совершеннолетие и явное согласие на съёмку и выбранное распространение. Отдельное согласие нужно для расширения аудитории."}, {"type": "heading", "text": "Недопустимые материалы"}, {"type": "paragraph", "text": "Запрещены материалы с несовершеннолетними, эксплуатация, принуждение, насилие без согласия, интимные изображения без разрешения, скрытая съёмка и сексуализированная подмена личности без согласия."}, {"type": "heading", "text": "Ограничения доступа"}, {"type": "paragraph", "text": "Закрытые материалы выдаются только после серверной проверки разрешения. После отзыва новые запросы должны отклоняться. Это не даёт технической гарантии от копирования получателем."}, {"type": "heading", "text": "До публикации заполнить"}, {"type": "paragraph", "text": "Допустимые категории для выбранных рынков и хостинга, процедура проверки согласия, экстренные обращения и правила удаления."}]$j$::jsonb,true);
    if (r->>'ok')<>'true' then raise exception 'save adult-content: %',r; end if;
    r:=public.feture_document_publish('adult-content','ru',1,true,clock_timestamp());
    if (r->>'ok')<>'true' then raise exception 'publish adult-content: %',r; end if;
  end if;
end $seed$;
select document_key, locale, version, effective_at from public.feture_document_current order by 1;
